# English for content/2569.py (same meeting numbers, same item order). tools/make_i18n.py zips it with the Thai
# into committees/health/i18n_en.json (csite.py adds it to the site's English dictionary).
# Rules as the Thai: neutral, no private names, complaints are claims, official English names of agencies.
IMG = ("(The Senate published the meeting summary as an image file. Please read the details in the original documents below.)")
EN = {}
EN[1] = dict(
 headline="Planning the subcommittees' work: primary health care and the health insurance budget",
 summary="The committee considered how its subcommittees will work. The subcommittee following primary health care set a framework to follow results after the Primary Health System Act B.E. 2562 in 5 areas: policy and plans, laws and rules, registration and standards of service units, service delivery, and staffing. It chose field visits to 5 areas, Bangkok, Chiang Mai, Khon Kaen, Nonthaburi and Narathiwat, to cover service units already transferred to local government and those not yet transferred, and areas with different levels of readiness. It will then invite the agencies that train health workers to find ways to solve staff shortages, before reporting to the committee. The committee also considered the work plan of the subcommittee studying the budget system, management and good governance under the National Health Security system.",
 items=["Work plan of the Subcommittee to Follow Progress on the Primary Health Care System (field visits to 5 areas)",
        "Work plan of the Subcommittee to Study the Budget System, Management and Good Governance under the National Health Security System"])
EN[2] = dict(
 headline="Effects of draft NHSO announcements on warm community clinics (innovative service units)",
 summary="Meeting on Tuesday 13 January 2569, according to the meeting notice. The agenda was a study of the facts on the problems and effects of drafting announcements of the National Health Security Office (NHSO), with groups of doctors and operators of warm community clinics (innovative service units) invited to give information. " + IMG,
 items=["Problems and effects of the draft NHSO announcements (hearing from groups of doctors and operators of warm community clinics)"])
EN[3] = dict(
 headline="2 draft NHSO announcements on innovative service units: reasons and effects",
 summary="The committee heard the intent and effects of 2 draft announcements of the National Health Security Office on paying for innovative medical services. Innovative service units are a partnership between private providers and the NHSO so that people can reach primary care easily and crowding in state hospitals is reduced. They grew to 7 types in 2567 under the “30 baht, treatment anywhere” policy. Today there are about 10,000 units, used about 31 million times in 2568. New rates include 100 baht per visit for diagnosis and advice, or 180 baht per visit including medicine and services (previously 320 baht). The NHSO explained 3 reasons: the risk of the budget growing out of control under open-ended payment, irregular claims found in some cases, and value for money compared with real costs.",
 items=["Intent and effects of the draft NHSO announcements on paying for innovative medical services (2 announcements)"])
EN[4] = dict(
 headline="Policy report on the health workforce: safe staff, safe patients",
 summary="The committee considered the draft report of the subcommittee on medical personnel, “Policy Proposals on Managing, Developing and Retaining the Health Workforce”. Key proposals include that staff safety equals patient safety, by pushing a draft act to protect the work of public health personnel that sets safe working hours; planning staff according to the real workload of each area; and fair pay according to workload and risk, with urgent, medium-term and long-term plans. The committee added observations such as spreading staff fairly across areas, the proportions in which staff are trained, and promoting family medicine doctors in every area.",
 items=["Draft report “Policy Proposals on Managing, Developing and Retaining the Health Workforce”"])
EN[5] = dict(
 headline="Vaccine against severe pneumococcal pneumonia (PCV) for Thai children",
 summary="The committee considered the policy on access to the PCV vaccine for Thai children under the National Health Security system, inviting the NHSO, the Department of Disease Control and the Royal College of Pediatricians of Thailand. It learned that the National Health Security Board approved a pilot of PCV vaccination in provinces or health regions with high illness rates that are ready to evaluate results, using the National Health Security Fund. The NHSO was asked to work with the Health Systems Research Institute and the Department of Disease Control to design an evaluation within 1 year, and to negotiate a price as close as possible to that of UNICEF or GAVI. The NHSO said it had proposed a new benefit of about 225 million baht, which the Cabinet has approved.",
 items=["Policy on access to vaccines against severe pneumococcal disease for Thai children (NHSO, Department of Disease Control, Royal College of Pediatricians)"])
EN[6] = dict(
 headline="PCV vaccine (continued): how new vaccines are added, with information from HITAP and the National Vaccine Institute",
 summary="The committee continued with the PCV vaccine, inviting the NHSO, the Health Intervention and Technology Assessment Program Foundation (HITAP) and the National Vaccine Institute. The National Vaccine Institute explained that a new vaccine is added through 3 mechanisms: the subcommittee on immunisation, the subcommittee on the National List of Essential Medicines, which considers value for money and budget burden, and the subcommittee under the National Health Security Board, which considers adding it to the benefit package. Work to introduce the PCV vaccine has gone on since 2560, including a pilot project in Maha Sarakham and the listing of PCV10 and PCV13 in the National List of Essential Medicines.",
 items=["Policy on access to the PCV vaccine (NHSO, HITAP and the National Vaccine Institute)"])
EN[7] = dict(
 headline="PCV vaccine (continued): value for money and evaluating the pilot",
 summary="The committee continued with the PCV vaccine, taking the view that making it a basic benefit should use information from all sides. HITAP reported its value-for-money study against the threshold of 160,000 baht per quality-adjusted life year, which depends on the vaccine price, treatment costs, target groups and herd immunity, and stressed that decisions must also consider other factors such as budget impact and equal access. The Health Systems Research Institute explained the design of the study to follow and evaluate the vaccination pilot with the NHSO. The committee also followed the draft announcement on the scope of vaccine services, the results of the public hearing and progress on buying the vaccine.",
 items=["Main points of the draft announcement on the scope of PCV vaccine services, public hearing results and procurement progress"])
EN[8] = dict(
 headline="Primary care field visits to Chiang Mai and Nonthaburi, and work on the health insurance budget",
 summary="The committee heard progress from 2 subcommittees. The primary health care subcommittee reported on its visit to Chiang Mai, which transferred all its sub-district health promoting hospitals to the Provincial Administrative Organization, in 5 areas: staff, infrastructure, information systems, disease screening, and finance. It also reported on Nonthaburi (20 Feb 2569), which still lacks family medicine doctors and where registration of service units is not yet complete, but which has outreach work such as “Healthy Condos” in urban communities. Proposals include designing staff management to fit the local context and rotating family medicine doctors to provide outreach services. The committee also heard progress from the subcommittee on budget and good governance in the National Health Security system.",
 items=["Progress of the primary health care subcommittee: field visits to Chiang Mai and Nonthaburi",
        "Progress of the subcommittee studying the budget system, management and good governance"])
EN[9] = dict(
 headline="Thailand's medicine security amid global conflicts, and the subcommittees' plans",
 summary="The committee heard progress from 2 subcommittees. It approved moving the field visits and seminars of the primary health care subcommittee to Khon Kaen (7–8 May 2569) and Chanthaburi (28–29 May 2569), and approved setting up a working group in the subcommittee on budget and good governance to draft a National Health Security Bill (No. ..), to propose ways to improve the law so that the system is sustainable. It then studied the country's medicine security in light of conflicts in several regions. The Thai Food and Drug Administration explained its approach in 4 areas, such as measures to oversee the prices of high-cost medicines and medical supplies in emergencies.",
 items=["Primary health care subcommittee: field visits and seminars in Khon Kaen and Chanthaburi rescheduled",
        "Working group set up to draft a National Health Security Bill (No. ..) B.E. ....",
        "Thailand's medicine security in light of conflicts around the world (Thai FDA)"])
EN[10] = dict(
 headline="Study of the Act on the Summoning Powers of Committees B.E. 2568",
 summary="The committee studied the principles, reasons and scope of the Act on the Summoning Powers of Committees of the House of Representatives and the Senate B.E. 2568, issued under section 129 of the Constitution. It allows committees to issue legally binding orders summoning persons and documents (including electronic documents) instead of asking for cooperation. It removes criminal penalties and uses disciplinary measures for state officials instead. Committees have no power to summon objects other than documents, and the provisions do not yet cover enforcement against members of the public or state officials who are not civil servants. The law is awaiting its regular evaluation every 5 years. The committee made observations so that the law can be used effectively.",
 items=["Principles, scope and results of the Act on the Summoning Powers of Committees B.E. 2568"])
EN[11] = dict(
 headline="New social security dental benefits (1 May 2569): wisdom tooth surgery, crowns and dental implants",
 summary="The committee considered the dental benefits of insured persons under the new announcement of the Medical Committee, effective 1 May 2569. The Social Security Office explained that the limit of 900 baht a year covers only fillings, scaling and extractions. Wisdom tooth surgery is a separate item of 1,500–2,500 baht depending on difficulty (including X-rays), and new benefits are added: crowns and dental implants. More than 2,000 state and more than 4,000 private facilities take part without patients paying first. Private clinics may charge the difference for fillings, scaling and extractions above 900 baht, but must always tell the insured person first, and may not charge extra for wisdom tooth surgery. At state facilities the benefit can be used without a limit on visits.",
 items=["Structure of dental benefits for insured persons and participation of service units (Social Security Office)"])
EN[12] = dict(
 headline="Thai Dental Council announcement on competency criteria for oral hygienists, and the work of dental nurses",
 summary="The committee considered the Thai Dental Council's announcement on competency criteria for oral hygienists (27 Mar 2569), which caused misunderstanding about the work of dental nurses. The Council explained that the announcement aims to develop the primary health care system and does not affect the role of dental nurses already working. It reported 3 problems: the lack of laws that fully cover dental professions, unclear staffing frameworks and career paths, and the lack of a dental staffing framework in sub-district health promoting hospitals transferred to local government. Proposals include having Provincial Administrative Organizations hire dentists, cooperation with the Ministry of Public Health, and more ways for dental nurses to become local government officials. The committee felt the matter should be explained correctly and widely, and stressed prevention because oral health is linked to chronic non-communicable diseases.",
 items=["Thai Dental Council announcement on competency criteria for oral hygienists (27 Mar 2569) and its effect on basic dental services"])
EN[13] = dict(
 headline="Withdrawal of recognition of a dentistry degree, and help for affected students",
 summary="The committee considered the Thai Dental Council's order withdrawing recognition of the Doctor of Dental Surgery degree of the Faculty of Dentistry, Nation University (curriculum of academic year 2562), which affects students of academic years 2563–2565. A representative of the Ministry of Higher Education, Science, Research and Innovation explained that the reasons given in the assessment were the qualifications of the lecturers responsible for the programme and the readiness of clinics and equipment. A group of parents submitted requests such as compensation, help in arranging transfers to accredited institutions, and fair credit transfer. The committee considered the steps for opening programmes, oversight and follow-up, and ways to help the students.",
 items=["Order withdrawing recognition of a Doctor of Dental Surgery degree: opening programmes, oversight and help for students"])
EN[14] = dict(
 headline="Warm community clinics in Bangkok raise delayed transfers of outpatient payments",
 summary="The committee considered progress on a request by the Warm Community Clinic Association to examine delayed transfers of capitation payments for outpatient services (OPCAP) in Bangkok (raised by the chair of the subcommittee concerned). The clinics said this causes a lack of cash, may affect the quality of services and could make service units near people's homes close, and asked that deductions and delays be clearly notified. Proposals are to review the payment mechanism to reflect real costs in Bangkok, open a forum between the NHSO and service units, and add transparency that can be checked. The committee felt that primary care in Bangkok has particular features that differ from the provinces.",
 items=["Request by the Warm Community Clinic Association to examine delayed transfers of outpatient payments (OPCAP) in Bangkok"])
EN[15] = dict(
 headline="Following emerging diseases: hantavirus, Ebola and COVID-19",
 summary="The committee followed the situation of emerging infectious diseases. The Department of Disease Control reported that the Andes strain of hantavirus that spread on a cruise ship can pass from person to person, with an incubation period of 1–8 weeks and early symptoms like influenza. Thailand has found no patients yet, but has raised it to the 14th dangerous communicable disease under the Communicable Diseases Act B.E. 2558, with measures in 4 areas: screening travellers from risk countries, preparing laboratories for confirmation tests, rehearsing plans to receive suspected patients, and communicating to prevent false news. Ebola has been found in Africa, and Thailand has found no infected persons.",
 items=["Situation of Ebola, hantavirus and COVID-19 and the effects on Thailand"])
EN[16] = dict(
 headline="Gender-affirming hormones in the gold card scheme",
 summary="The committee studied adding gender-affirming hormones as a benefit in the National Health Security system, covering criteria, the readiness of services, safety and budget impact. The NHSO explained that the work has developed since 2563. These hormone medicines are already in the National List of Essential Medicines, so they can be a basic service, covering people aged 18 and over who need them, so that they receive the medicines correctly. The National Health Security Board approved them as a health promotion and disease prevention benefit.",
 items=["Adding gender-affirming hormones as a National Health Security benefit (NHSO)"])
EN[17] = dict(
 headline="New National Health Security Bill drafted by the subcommittee",
 summary="The committee considered the National Health Security Bill B.E. ...., drafted by the working group of the subcommittee on budget and good governance together with representatives of the Office of the Council of State, based on agencies' comments and public hearings in all 4 regions. The main change is to move from a clear split between purchasers and providers of services to joint management that defines the roles of purchasers, providers and regulators clearly and has them work together from the start. Benefits are divided into 3 levels: essential basic services, extra services specific to each fund, and other services for which users may co-pay voluntarily. The announcement on the scope of basic services is to be reviewed every 3 years, and the membership of the National Health Security Board balanced between fund administrators and experts, service users, and service providers. The committee also set the issues for hearing the views of the public and agencies.",
 items=["National Health Security Bill B.E. .... and issues for the public hearing"])
EN[18] = dict(
 headline="Gender-affirming hormones (continued): views of the royal colleges of physicians",
 summary="The committee continued to consider providing gender-affirming hormones as a benefit, covering criteria, clinical practice guidelines, safety and budget. The Royal College of Physicians of Thailand confirmed that it is a necessary medical service that must follow professional standards with continuous assessment and follow-up, and proposed national clinical practice guidelines made with multiple professions and a registry for long-term follow-up. The Royal College of Pediatricians of Thailand made observations on services for children and adolescents, long-term health effects, and mental and psychosocial care. The Royal College of Psychiatrists of Thailand said that gender identity is not an illness, but some people with gender incongruence need hormones, and adolescents must be assessed in all respects.",
 items=["Providing gender-affirming hormones as a benefit: criteria, clinical practice guidelines, safety and budget"])
EN[19] = dict(
 headline="Gender-affirming hormones (continued): the NHSO explains how benefits are set",
 summary="The committee heard the Secretary-General of the National Health Security Office, who explained that section 5 of the National Health Security Act B.E. 2545 covers treatment, health promotion and disease prevention, and that the 2565 announcement on the scope of services uses an exclusion principle: services not excluded are benefits, except procedures for appearance without a medical indication or treatments still being tested. The NHSO reviews benefits every year by assessing safety and value for money (HTA), and the National Health Security Board also considers ethics, the readiness of services and quality of life when deciding.",
 items=["Setting the gender-affirming hormone benefit in the National Health Security system (NHSO Secretary-General)"])
EN[20] = dict(
 headline="Study of the amended bill to protect and promote Thai traditional medicine wisdom",
 summary="The committee studied the Protection and Promotion of Thai Traditional Medicinal Intelligence Bill (No. ..) under rule 119 of the Rules of Procedure of the Senate, inviting the Department of Thai Traditional and Alternative Medicine and the Office of the Council of State. It has 3 main points: communities may register together as owners of traditional knowledge, and if a community ceases to exist the knowledge is protected as national knowledge; commercial use of the knowledge is adjusted and sources of income for the Thai traditional medicine wisdom fund are added; and the Director-General may grant permission and settle fines, with heavier penalties for commercial use without permission. A representative of the Council of State observed that recognising community rights may add paperwork, and suggested community representatives and benefit sharing.",
 items=["Protection and Promotion of Thai Traditional Medicinal Intelligence Bill (No. ..) B.E. .... (rule 119)"])
EN[21] = dict(
 headline="Report on the Thai traditional medicine bill with 6 proposals, and a report on primary health care work",
 summary="The committee considered the draft study report on the Protection and Promotion of Thai Traditional Medicinal Intelligence Bill, with 6 proposals, such as: common herbal formulas used in many areas should not be monopolised by any one community but should be national formulas; speeding up the survey and registration of herb-growing areas as protected areas; building a digital database of traditional knowledge for patent offices around the world to check (as in India); using the fund to support research and to bring herbal medicines into the National List of Essential Medicines; defining “community” clearly and giving it legal status; and coordinating policy between ministries. It also considered the draft report on primary health care work of the subcommittee concerned.",
 items=["Draft study report on the Protection and Promotion of Thai Traditional Medicinal Intelligence Bill (rule 119)",
        "Draft report on primary health care work (primary health care subcommittee)"])
EN[22] = dict(
 headline="Report on reforming health insurance: prices at real cost, separate staff budget and a national basic benefit package",
 summary="The committee considered the draft report of the Subcommittee to Study the Budget System, Management and Good Governance under the National Health Security System. Key proposals are: adjust inpatient reference prices to reflect real costs and review them every 2 years; separate the staff budget from the capitation budget and allocate service budgets by actual tasks and workload; set a national basic service package that everyone receives equally, with possible voluntary co-payment for services beyond it without affecting people on low incomes and vulnerable groups; and improve governance, such as the make-up of the board, terms of no more than 2, and protection for staff. The work is planned in 3 phases, from gathering information and public hearings to enforcing the law.",
 items=["Draft study report of the Subcommittee to Study the Budget System, Management and Good Governance"])
EN[23] = dict(
 headline="Making Parliament's rules consistent with the tobacco control convention",
 summary="Meeting on Tuesday 8 September 2569, according to the meeting notice. The agenda was a study of ways to bring Parliament's regulations in line with obligations under the tobacco control convention (Article 5.3 of the WHO Framework Convention on Tobacco Control, on protecting policy from interference by the tobacco industry), including problems and obstacles, with academic experts invited to give information. " + IMG,
 items=["Bringing Parliament's regulations in line with the tobacco control convention (WHO FCTC Article 5.3)"])
EN[24] = dict(
 headline="Protecting policy from tobacco industry interference: hearing the Department of Disease Control",
 summary="The committee considered Thailand's situation and approach in following Article 5.3 of the WHO Framework Convention on Tobacco Control. The Department of Disease Control explained that it has a 2555 department regulation on contact with tobacco operators, requiring contact only as necessary, transparent and open to checking, preventing conflicts of interest, and refusing sponsorship from the tobacco industry. Its limits are that the regulation applies only to the Department of Disease Control, not yet to other agencies such as the Excise Department, and has no penalties. The department will therefore prepare guidelines against interference for state agencies, and push through the National Tobacco Products Control Committee for a regulation of the Office of the Prime Minister on this matter.",
 items=["Situation and approach in following Article 5.3 of the tobacco control convention (Department of Disease Control)"])
EN[25] = dict(
 headline="Reforming the state workforce under the OCSC letter: concerns of public health staff",
 summary="The committee considered the approach to reforming the management of the state workforce under the letter of the Office of the Civil Service Commission (4 Sep 2569) and its effects on the positions, careers and staffing of public health personnel. Representatives of 15 staff associations said the announcement made staff worried and lowered morale. Promotion submissions made since 2567 are still delayed, while several professions face serious shortages, such as radiologic technologists, medical technologists, Thai traditional medicine practitioners and registered nurses. They proposed finishing the promotion assessments pending from 2567 within fiscal year 2569, reviewing the circular letter, and developing career paths that match the real workload. A representative of the OCSC explained the reasons for and approach of the measures.",
 items=["Approach to reforming state workforce management (OCSC letter of 4 Sep 2569) and its effects on public health personnel"])
EN[26] = dict(
 headline="Preparing the forum “The Facts on the Gold Card Bill | What Does the Committee Say?” part 2",
 summary="This meeting was moved from 28 to 29 September 2569. The committee reviewed part 1 of the forum, “Improving the Gold Card Law: Intent, Facts and What People Should Know” (23 Sep 2569), and agreed to hold part 2 on restructuring the board and participation before benefits are set, using the PCV vaccine and gender-affirming hormones as case studies. Suggestions included dividing the forum into 2 sessions and moving the board structure topic to the next event, improving the picture and sound of the live broadcast, and making invitation materials easier to understand.",
 items=["Holding the forum “The Facts on the Gold Card Bill | What Does the Committee Say?” part 2"])
EN[27] = dict(
 headline="Finances of Ministry of Public Health hospitals, 2566–2568",
 summary="The committee considered the finances of hospitals under the Ministry of Public Health over the past 3 years, inviting representatives of the Permanent Secretary of Public Health and the Health Economics and Health Security Division. The main problem is that income does not match costs, while older persons and patients with chronic diseases are increasing and some reimbursement rates still do not reflect real costs, so many hospitals have negative maintenance funds, affecting cash flow and the continuity of services. The ministry has made financial management more integrated, such as taking part in allocating the National Health Security Fund in 2569 and using a financial crisis scale of 0–7 with an early warning system.",
 items=["Finances of hospitals under the Ministry of Public Health (fiscal years 2566–2568) and solutions"])
EN[28] = dict(
 headline="Hospital finances (continued): hearing the association of regional and general hospitals and hospitals in the field",
 summary="The committee continued to study the finances of hospitals under the Office of the Permanent Secretary for Public Health. The chair of the association of regional and general hospitals reported 93 hospitals at financial risk level 7 (mostly community hospitals) and 540 service units, or about 59 percent, with negative maintenance funds. The director of a network hospital in Chiang Mai described a shortage of cash at the end of fiscal year 2569, which affected buying medicines and medical supplies, because of several outstanding debts, including treatment costs for migrant workers. The committee considered the effects on buying medicines and supplies and on staff management, and possible solutions.",
 items=["Finances of hospitals under the Office of the Permanent Secretary for Public Health: income, spending, maintenance funds and debts"])
EN[29] = dict(
 headline="Community hospital finances, and standards for care centres for older persons",
 summary="The committee heard the chair of the Association of Community Hospital Directors of Thailand, who said community hospitals' income has grown but spending has grown faster, especially for small hospitals serving few people, and budget allocation and service payments still do not match costs. The committee proposed, for example, reviewing allocation and payment criteria to match the real costs and workload of hospitals at each level, a mechanism to support cash flow together with recovery plans, speeding up payments and outstanding debts, and sharing resources at province and health region level. It also took up a news report about a care centre for older persons and dependent patients in Kanchanaburi to consider standards and safety of care.",
 items=["Finances of community hospitals (Association of Community Hospital Directors of Thailand)",
        "Standards and safety in the care of older persons, following news about a care centre in Kanchanaburi"])
EN[30] = dict(
 headline="Standards of care for older persons and dependent patients in care facilities",
 summary="Meeting on Tuesday 3 November 2569, according to the meeting notice. The agenda was a study, following news about a care centre for older persons and dependent patients in Kanchanaburi, of the standards and safety of care facilities, and of setting criteria and standards for the care of older persons and people with dependency, including people with drug addiction or psychiatric disorders. " + IMG,
 items=["Standards and safety in the care of older persons and dependent patients in facilities, and criteria for care"])
EN[31] = dict(
 headline="Developing care for older persons and people with dependency, and protecting the safety of service users",
 summary="Meeting on Tuesday 10 November 2569, according to the meeting notice. The agenda was a study of developing care for older persons, people with dependency and people who need special care, including protecting the rights and safety of service users, continuing from the news about a care centre for older persons in Kanchanaburi and the admission of people with drug addiction or psychiatric disorders into care businesses for older persons. " + IMG,
 items=["Developing care for older persons and people with dependency, and protecting the rights and safety of service users"])
EN[32] = dict(
 headline="Agreeing in principle to set up a subcommittee on the health of older persons and social welfare",
 summary="The committee considered setting up a subcommittee, as the Subcommittee to Follow Progress on the Primary Health Care System has finished its work and reported to the Senate. A vice-chair of the committee proposed a subcommittee to study all aspects of older persons and people with dependency, continuing from the previous meeting on the care of older persons and the safety of service users. An adviser to the committee presented a study framework, for example linking the health system, long-term care and social protection with older persons and their families at the centre, linking data between agencies safely under the personal data protection law, reviewing the NHSO's long-term care budget allocation, and studying local models such as in Chiang Mai, Phuket and Songkhla, over about 3 months (March–May 2570). Committee members observed, for example, that family institutions should be strengthened, financial literacy of older persons promoted, and people prepared from working age. The committee agreed in principle to set up a subcommittee on developing the public health system, the health of older persons and social welfare, and agreed to hold part 5 of the forum “The Facts on the Gold Card Bill | What Does the Committee Say?” on Wednesday 9 December 2569.",
 items=["Setting up a subcommittee on developing the public health system, the health of older persons and social welfare (agreed in principle)",
        "Holding the forum “The Facts on the Gold Card Bill | What Does the Committee Say?” part 5 (Wednesday 9 December 2569)"])
EN[33] = dict(
 headline="Work of the Thai Health Promotion Foundation (ThaiHealth)",
 summary="Meeting on Tuesday 1 December 2569 at 08.00, committee meeting room CA 429, 4th floor, Parliament House, according to the meeting notice. The agenda is a study of the work of the Thai Health Promotion Foundation (ThaiHealth) under the Health Promotion Foundation Act of 2001, for example the fund's intent and role, the results of its projects, management of income and budget, grants to outside agencies, management of accumulated funds and assets, oversight and evaluation, and ways to improve the law or the fund's management, with the manager of the Thai Health Promotion Foundation invited to attend. The summary will be added after the Senate publishes it.",
 items=["The work of the Thai Health Promotion Foundation (ThaiHealth) under the Health Promotion Foundation Act of 2001"])

